import AppKit

/// The Color sub-tab's last section, **Look** (spec §11 GR-7 [b], grading
/// GR5b): the gallery of the eight built-in looks and None, the
/// imported LUTs and Import LUT… (GR-8 [b], GR6b), and an Amount row when
/// every selected clip has a look.
///
/// A tile (a LUT's too), None and Reset write the clips' OWN look in one
/// `set_video`, even with an action selected (GR-7 [b] (1)): in an action's
/// end `look: null` only stops animating the look, so it could not remove
/// one, and the kind switches at the end anyway. The Amount row is the one
/// that animates: it goes through `binding.ops(video:)` like every number.
extension VideoPane {
    // MARK: Look

    /// Every selected clip that draws has a look (evaluated, as the rows
    /// read); false for no such clip. `ClipPane`'s structure signature reads
    /// it, since it adds or removes the Amount row.
    var allLooked: Bool {
        let clips = binding.videoClips
        return !clips.isEmpty && clips.allSatisfy { binding.video($0).look != nil }
    }

    /// Some selected clip's look is a LUT and its source file is converted
    /// by Camera Log (spec §11 GR-16): a camera LUT applied as a look would
    /// then convert it twice. `ClipPane`'s structure signature reads it, since
    /// it adds or removes the warning row.
    var lutOverCameraLog: Bool {
        let snapshot = binding.snapshot
        return binding.videoClips.contains { clip in
            guard binding.video(clip).look?.kind == .lut,
                let media = clip.source.mediaID, snapshot.media(media)?.color != nil
            else { return false }
            return true
        }
    }

    /// Some selected clip's look is a LUT and the project is HDR (HLG), where
    /// a `.cube` LUT still reads its values as Rec. 709 (spec §11 HD-2, HD-13
    /// (k)). `ClipPane`'s structure signature reads it, since it adds or
    /// removes the warning row.
    var lutInHLG: Bool {
        binding.snapshot.canvas.output == .hlg
            && binding.videoClips.contains { binding.video($0).look?.kind == .lut }
    }

    func lookSection(_ gallery: LookGallery) -> InspectorSection {
        let binding = self.binding
        func ids() -> [UInt32] { binding.videoClips.map(\.id) }
        func looks() -> [LookProps?] { binding.videoClips.map { binding.video($0).look } }
        func names() -> [UInt32: String] {
            var names: [UInt32: String] = [:]
            for lut in LookGallery.luts(in: binding.snapshot) {
                names[lut.id] = LookGallery.lutName(lut)
            }
            return names
        }
        let view = LookGalleryView(
            gallery: gallery, binding: binding,
            onPick: { binding.apply("Look", [LookGallery.op($0, clips: ids())]) },
            onPickLUT: { binding.apply("Look", [LookGallery.op(lut: $0, clips: ids())]) },
            onImport: { [weak self] in
                self?.inspector?.onCommand?(#selector(EditorViewController.importLUT(_:)))
            })
        var rows: [NSView] = [view]
        if lutOverCameraLog {
            // A warning only: a creative LUT there is legitimate (GR-16).
            let warning = InspectorRowLabel(
                "This clip's file is converted by Camera Log; a camera LUT here converts it "
                    + "twice.")
            warning.lineBreakMode = .byWordWrapping
            warning.maximumNumberOfLines = 0
            rows.append(inspectorRow(nil, [warning]))
        }
        if lutInHLG {
            // A warning only, as GR-16's: a LUT keeps its 0…1 meaning.
            let warning = InspectorRowLabel(
                "This project is HDR (HLG): a .cube LUT reads its values as Rec. 709.")
            warning.lineBreakMode = .byWordWrapping
            warning.maximumNumberOfLines = 0
            rows.append(inspectorRow(nil, [warning]))
        }
        rows += allLooked ? [
            inspectorValueRow(
                "Amount", binding, name: "Amount", unit: "%", decimals: 0, min: 0, max: 100,
                quick: [0, 25, 50, 75, 100],
                read: { (binding.videoProps.look?.amount ?? 1) * 100 },
                ops: { binding.ops(video: VideoPatch(look: .some(LookPatch(amount: $0 / 100)))) },
                mixed: { binding.mixedVideo { $0.look?.amount } }),
        ] : []
        return InspectorSection(
            id: "video.look", title: "Look",
            summary: { LookGallery.summary(looks(), names: names()) },
            reset: { binding.apply("Look", [LookGallery.op(nil, clips: ids())]) },
            differs: { looks().contains { $0 != nil } },
            defaultExpanded: false,
            rows: rows)
    }
}
import AppKit

/// The Look section's gallery (spec §11 GR-7 [b]): a 3×3 grid of tiles —
/// None, then the eight looks in `LookGallery.tiles` order — each a thumbnail
/// with its name beneath, the kind every target shares outlined in the accent;
/// under it the Imported group, a tile per `.cube` LUT in rows of three (spec
/// §11 GR-8 [b]), then the Import LUT… button.
///
/// An `OptionControl`, so the section's `refresh()` reaches it like any row:
/// each refresh hands the model the selection and whether the gallery is OPEN —
/// in a window and not hidden, which a collapsed section's content is. Open
/// and closed are read here, from `isHiddenOrHasHiddenAncestor`, and the three
/// moments they change (`viewDidHide`, `viewDidUnhide`, `viewDidMoveToWindow`)
/// refresh too; never from `InspectorSection.didToggle`, which `KeyedReveal`
/// overwrites on every build.
final class LookGalleryView: NSView, OptionControl {
    let tiles: [LookTileButton]
    let lutTiles: [LookTileButton]
    let importButton: NSButton
    private let gallery: LookGallery
    private let binding: InspectorBinding
    private let onPick: (LookKind?) -> Void
    private let onPickLUT: (UInt32) -> Void
    private let onImport: () -> Void

    init(
        gallery: LookGallery, binding: InspectorBinding, onPick: @escaping (LookKind?) -> Void,
        onPickLUT: @escaping (UInt32) -> Void, onImport: @escaping () -> Void
    ) {
        self.gallery = gallery
        self.binding = binding
        self.onPick = onPick
        self.onPickLUT = onPickLUT
        self.onImport = onImport
        tiles = LookGallery.tiles.map { LookTileButton(kind: $0) }
        lutTiles = LookGallery.luts(in: binding.snapshot).map {
            LookTileButton(kind: .lut, lut: $0)
        }
        importButton = StickerButton(
            title: "Import LUT…", style: .secondary, target: nil, action: nil)
        super.init(frame: .zero)
        translatesAutoresizingMaskIntoConstraints = false
        let grid = NSStackView()
        grid.orientation = .vertical
        grid.alignment = .leading
        grid.spacing = 6
        grid.translatesAutoresizingMaskIntoConstraints = false
        addSubview(grid)
        NSLayoutConstraint.activate([
            grid.topAnchor.constraint(equalTo: topAnchor),
            grid.bottomAnchor.constraint(equalTo: bottomAnchor),
            grid.leadingAnchor.constraint(equalTo: leadingAnchor),
            grid.trailingAnchor.constraint(equalTo: trailingAnchor),
        ])
        for start in stride(from: 0, to: tiles.count, by: 3) {
            let row = NSStackView(views: Array(tiles[start..<min(start + 3, tiles.count)]))
            row.orientation = .horizontal
            row.distribution = .fillEqually
            row.alignment = .top
            row.spacing = 6
            grid.addArrangedSubview(row)
            row.widthAnchor.constraint(equalTo: grid.widthAnchor).isActive = true
        }
        if let first = tiles.first, !lutTiles.isEmpty {
            let label = NSTextField(labelWithString: "Imported")
            label.font = DS.sans(10)
            label.textColor = DS.textMuted
            grid.addArrangedSubview(label)
            // Each LUT tile is a built-in tile's width, so a short last row
            // keeps third-width tiles.
            for start in stride(from: 0, to: lutTiles.count, by: 3) {
                let row = NSStackView(
                    views: Array(lutTiles[start..<min(start + 3, lutTiles.count)]))
                row.orientation = .horizontal
                row.distribution = .fill
                row.alignment = .top
                row.spacing = 6
                grid.addArrangedSubview(row)
            }
            for tile in lutTiles {
                tile.widthAnchor.constraint(equalTo: first.widthAnchor).isActive = true
            }
        }
        // The house square block (sharp pass), at the inspector's control height.
        importButton.font = DS.sans(11)
        importButton.heightAnchor.constraint(equalToConstant: DS.controlHeight).isActive = true
        importButton.toolTip = "Import a .cube file and apply it to the selected clips"
        importButton.target = self
        importButton.action = #selector(importPicked(_:))
        grid.addArrangedSubview(importButton)
        for tile in tiles + lutTiles {
            tile.target = self
            tile.action = #selector(tilePicked(_:))
        }
        gallery.view = self
        showThumbnails()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("LookGalleryView does not support NSCoder")
    }

    /// Whether this gallery is the attached one and owes renders — what
    /// `select_inspector_tab` answers as `look_thumbnails_pending`.
    var isPending: Bool { gallery.view === self && gallery.isPending }

    func refresh() {
        let targets = LookGallery.targets(binding.clips, in: binding.snapshot)
        gallery.update(
            from: self, document: binding.document, targets: targets,
            open: window != nil && !isHiddenOrHasHiddenAncestor)
        // The outline reads the clips' OWN looks, which is what a tile writes
        // (GR-7 [b] (1)), as Clip ▸ Look ▸'s checkmarks do.
        let shared = LookGallery.shared(targets.map { $0.videoProps.look })
        for tile in tiles {
            tile.isOutlined = shared.map { $0 == tile.kind } ?? false
        }
        for tile in lutTiles {
            tile.isOutlined = !targets.isEmpty && targets.allSatisfy {
                $0.videoProps.look?.kind == .lut && $0.videoProps.look?.media == tile.media
            }
        }
        importButton.isEnabled = !targets.isEmpty
    }

    /// The model's thumbnails, onto the tiles.
    func showThumbnails() {
        guard gallery.view === self else { return }
        for (tile, image) in zip(tiles, gallery.thumbnails) { tile.thumbnail = image }
        for tile in lutTiles { tile.thumbnail = tile.media.flatMap { gallery.lutThumbnails[$0] } }
    }

    override func viewDidMoveToWindow() {
        super.viewDidMoveToWindow()
        refresh()
    }

    override func viewDidHide() {
        super.viewDidHide()
        refresh()
    }

    override func viewDidUnhide() {
        super.viewDidUnhide()
        refresh()
    }

    @objc private func tilePicked(_ sender: LookTileButton) {
        if let media = sender.media { onPickLUT(media) } else { onPick(sender.kind) }
    }

    @objc private func importPicked(_ sender: Any?) {
        onImport()
    }
}

/// One tile: a well holding the thumbnail, aspect-fit, and the look's name
/// beneath; outlined in the accent when every target carries its kind. A LUT's
/// tile (`lut`) is kind `lut`, its `media` the LUT's id, its name the file's.
final class LookTileButton: NSButton {
    let kind: LookKind?
    let media: UInt32?
    var isOutlined = false {
        didSet { if isOutlined != oldValue { needsDisplay = true } }
    }
    var thumbnail: CGImage? {
        didSet { if thumbnail !== oldValue { needsDisplay = true } }
    }
    private let well = NSView()
    private let name: NSTextField

    init(kind: LookKind?, lut: MediaSnapshot? = nil) {
        self.kind = kind
        media = lut?.id
        let title = lut.map(LookGallery.lutName) ?? kind?.displayName ?? "None"
        name = NSTextField(labelWithString: title)
        super.init(frame: .zero)
        self.title = ""
        isBordered = false
        imagePosition = .noImage
        setButtonType(.momentaryChange)
        translatesAutoresizingMaskIntoConstraints = false
        setAccessibilityLabel(title)
        toolTip = kind == nil ? "Remove the look" : "Apply \(title)"

        well.translatesAutoresizingMaskIntoConstraints = false
        addSubview(well)
        name.font = DS.sans(10)
        name.textColor = DS.textMuted
        name.alignment = .center
        name.lineBreakMode = .byTruncatingTail
        name.translatesAutoresizingMaskIntoConstraints = false
        name.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        addSubview(name)
        NSLayoutConstraint.activate([
            well.topAnchor.constraint(equalTo: topAnchor),
            well.leadingAnchor.constraint(equalTo: leadingAnchor),
            well.trailingAnchor.constraint(equalTo: trailingAnchor),
            well.heightAnchor.constraint(equalTo: well.widthAnchor, multiplier: 9.0 / 16.0),
            name.topAnchor.constraint(equalTo: well.bottomAnchor, constant: 3),
            name.leadingAnchor.constraint(equalTo: leadingAnchor),
            name.trailingAnchor.constraint(equalTo: trailingAnchor),
            name.bottomAnchor.constraint(equalTo: bottomAnchor),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("LookTileButton does not support NSCoder")
    }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: NSView.noIntrinsicMetric)
    }

    override func draw(_ dirtyRect: NSRect) {
        let frame = well.frame
        DS.canvasVoid.setFill()
        frame.fill()
        if let thumbnail, thumbnail.width > 0, thumbnail.height > 0,
           let context = NSGraphicsContext.current?.cgContext
        {
            let scale = min(
                frame.width / CGFloat(thumbnail.width), frame.height / CGFloat(thumbnail.height))
            let size = CGSize(
                width: CGFloat(thumbnail.width) * scale, height: CGFloat(thumbnail.height) * scale)
            let rect = CGRect(
                x: frame.midX - size.width / 2, y: frame.midY - size.height / 2,
                width: size.width, height: size.height)
            context.saveGState()
            context.interpolationQuality = .high
            if isFlipped {
                context.translateBy(x: 0, y: rect.maxY + rect.minY)
                context.scaleBy(x: 1, y: -1)
            }
            context.draw(thumbnail, in: rect)
            context.restoreGState()
        }
        let outline = isOutlined ? DS.accent : DS.border
        let width: CGFloat = isOutlined ? 2 : 1
        outline.setStroke()
        let path = NSBezierPath(rect: frame.insetBy(dx: width / 2, dy: width / 2))
        path.lineWidth = width
        path.stroke()
    }
}
import Foundation

// MARK: - Looks' value types (road map grading, spec §11 GR-7)

/// The eight built-in looks, in `model_look.rs`'s declaration order — the
/// gallery's and the menu's order (append, never reorder) — and `lut`, an
/// imported `.cube` file (spec §11 GR-8), which is not one of `builtIns`.
/// Closed, and
/// decoded by RAW VALUE, so `JSONDecoder`'s `.convertFromSnakeCase` never
/// touches these spellings. The core is the one place a look is DEFINED; this
/// side only names them and reads the definition the recipe publishes.
enum LookKind: String, Codable, CaseIterable {
    case warm
    case cool
    case tealOrange = "teal_orange"
    case vivid
    case faded
    case vintage
    case dramatic
    case blackWhite = "black_white"
    case lut

    /// The eight built-in looks, the gallery's tiles and the menu's items.
    static let builtIns: [LookKind] = allCases.filter { $0 != .lut }

    var displayName: String {
        switch self {
        case .warm: return "Warm"
        case .cool: return "Cool"
        case .tealOrange: return "Teal & Orange"
        case .vivid: return "Vivid"
        case .faded: return "Faded"
        case .vintage: return "Vintage"
        case .dramatic: return "Dramatic"
        case .blackWhite: return "Black & White"
        case .lut: return "LUT"
        }
    }
}

/// A clip's stored look, `video.look`: which, and how much (0…1), and for a
/// `lut` look its media id (GR-8). Absent — nil on `VideoProps` — is no
/// look. A `look` with no readable kind decodes as nil, which is what the
/// core makes of one too.
struct LookProps: Codable, Equatable {
    let kind: LookKind
    let amount: Double
    let media: UInt32?

    init(kind: LookKind, amount: Double = 1, media: UInt32? = nil) {
        self.kind = kind
        self.amount = amount
        self.media = media
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        kind = try c.decode(LookKind.self, forKey: .kind)
        amount = c.lenient(.amount, 1)
        media = c.lenient(.media)
    }
}

/// What a look write SENDS: a kind, an amount, or both, and a LUT's `media`
/// with kind `lut` (GR-8). A kind alone keeps each clip's amount (1 on a clip
/// with none, the core's default); an amount alone is refused by the core on
/// a clip with no look. Removing the look is `VideoPatch.look = .some(nil)`.
struct LookPatch: Codable, Equatable {
    var kind: LookKind?
    var amount: Double?
    var media: UInt32?

    init(kind: LookKind? = nil, amount: Double? = nil, media: UInt32? = nil) {
        self.kind = kind
        self.amount = amount
        self.media = media
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        kind = c.lenient(.kind)
        amount = c.lenient(.amount)
        media = c.lenient(.media)
    }

    var dictionary: [String: Any] {
        var d: [String: Any] = [:]
        if let kind = kind { d["kind"] = kind.rawValue }
        if let amount = amount { d["amount"] = amount }
        if let media = media { d["media"] = media }
        return d
    }
}

/// A look's split tone, as the recipe publishes it: two hues in degrees,
/// each with an amount 0…1. Mirrors `model_look.rs`'s `SplitTone`.
struct SplitTone: Codable, Hashable {
    let shadowHue: Double
    let shadowAmount: Double
    let highlightHue: Double
    let highlightAmount: Double

    static let none = SplitTone(shadowHue: 0, shadowAmount: 0, highlightHue: 0, highlightAmount: 0)
}

extension SplitTone {
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        shadowHue = c.lenient(.shadowHue, 0)
        shadowAmount = c.lenient(.shadowAmount, 0)
        highlightHue = c.lenient(.highlightHue, 0)
        highlightAmount = c.lenient(.highlightAmount, 0)
    }
}

/// What a look IS — the colour (all thirteen keys) and split tone its
/// lattice is baked from, read off the recipe. Hashable because it is
/// `LookTextures`' cache key: two layers with one definition share a bake.
struct LookDefinition: Codable, Hashable {
    let color: ColorAdjust
    let split: SplitTone

    /// The definition that bakes the identity lattice.
    static let identity = LookDefinition(color: .identity, split: .none)
}

extension LookDefinition {
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        color = c.lenient(.color, ColorAdjust.identity)
        split = c.lenient(.split, SplitTone.none)
    }
}

/// A recipe layer's `look` (spec §7.3): how much, and the definition to
/// bake — or, for a LUT look (GR-8), the media whose `.cube` file to draw,
/// with no definition. The core publishes `null` for no look, an amount of 0
/// and an ungraded frame, so a non-nil one always has an amount above 0; its
/// kind is on the wire for a reader and is not needed to draw.
struct RecipeLook: Codable, Equatable {
    let amount: Double
    let definition: LookDefinition
    let media: UInt32?

    init(amount: Double, definition: LookDefinition, media: UInt32? = nil) {
        self.amount = amount
        self.definition = definition
        self.media = media
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        amount = c.lenient(.amount, 0)
        definition = c.lenient(.definition, LookDefinition.identity)
        media = c.lenient(.media)
    }
}

extension LayerUniforms {
    /// The look's two floats (spec §11 GR-7): step 4d's mix, 0…1, and
    /// `lookEnabled`, 1 exactly when there is a look with an amount above 0
    /// — the effects gate's term, so a look-less layer never samples
    /// `texture(2)` and renders byte-identical.
    mutating func apply(look: RecipeLook?) {
        let amount = look?.amount ?? 0
        lookAmount = Float(min(max(amount, 0), 1))
        lookEnabled = look != nil && amount > 0 ? 1 : 0
    }
}
