3	/// The Look section's gallery model (spec §11 GR-7 [b], grading GR5b):
4	/// which clips a look applies to, the op a tile or a menu item sends,
5	/// and the nine thumbnails — None and the eight — each the composited frame
6	/// with that tile's click applied, then one per imported `.cube` LUT (spec
7	/// §11 GR-8 [b]), in the media list's order.
8	///
9	/// **It lives on `ClipPane`, not on the view**, because the pane rebuilds its
10	/// sections on every structure change and a thumbnail set that died with each
11	/// build would re-render for nothing. A view attaches itself (`view`) when it
12	/// is built, and an update from any other view — a retired build's late
13	/// `viewDidMoveToWindow` — is ignored.
14	///
15	/// **When it renders.** Its inputs are the edited project's HANDLE, the target
16	/// ids and the thumbnail time. An update or a playhead poke with the inputs it
17	/// last scheduled does nothing; anything else re-arms one `settle` timer, so a
18	/// playhead moving every frame (playback, a scrub) never renders. The timer
19	/// renders only if the gallery is open then (its section expanded, its window
20	/// there); hiding it or leaving the window cancels the timer and supersedes a
21	/// running generation. A generation applies the trial ops (the nine, then one
22	/// per LUT) on main and renders them off main, one tile after another, through
23	/// `Exporter.renderFrame` — `render_frame`'s renderer, so a thumbnail is the
24	/// pixels that tool writes (its file carries PR-11's label; a tile's dump is
25	/// unlabelled, spec §11 PR-11) —
26	/// with `RecipeOptions.none` (thumbnails ignore Show Ungraded, as an export
27	/// does). A superseded generation skips its remaining tiles, and its results
28	/// never land.
29	final class LookGallery {
30	    /// None, then the eight in the core's order: the gallery's reading order.
31	    static let tiles: [LookKind?] = [nil] + LookKind.builtIns.map { Optional($0) }
32	    static let thumbnailWidth = 256
33	    static let settle: TimeInterval = 0.3
34	    #if FRAMEJOB_DEV_TOOLS
35	    /// A launch default naming a folder: each completed generation N writes
36	    /// `<folder>/<N>/<tile>.png` and then `<folder>/<N>/manifest.json`.
37	    static let dumpKey = "RCDevLookGalleryDump"
38	    #endif
39	
40	    private(set) var thumbnails: [CGImage?] = Array(repeating: nil, count: tiles.count)
41	    /// The Imported group's thumbnails, by the LUT's media id.
42	    private(set) var lutThumbnails: [UInt32: CGImage] = [:]
43	    /// The attached view; an update from any other is ignored.
44	    weak var view: LookGalleryView?
45	
46	    private struct Inputs {
47	        let project: ReelProject
48	        let ids: [UInt32]
49	        let time: Ticks
50	
51	        func same(_ other: Inputs?) -> Bool {
52	            guard let other else { return false }
53	            return project === other.project && ids == other.ids && time == other.time
54	        }
55	    }
56	
57	    /// A generation's cancel flag, read off main between tiles.
58	    private final class Token {
59	        private let lock = NSLock()
60	        private var cancelled = false
61	        func cancel() {
62	            lock.lock()
63	            cancelled = true
64	            lock.unlock()
65	        }
66	        var isCancelled: Bool {
67	            lock.lock()
68	            defer { lock.unlock() }
69	            return cancelled
70	        }
71	    }
72	
73	    private weak var document: ProjectDocument?
74	    private var targets: [ClipSnapshot] = []
75	    private var open = false
76	    /// What the last update or poke asked for, what was last scheduled (timer
77	    /// armed, rendering or rendered), and what the thumbnails show.
78	    private var latest: Inputs?
79	    private var scheduled: Inputs?
80	    private var rendered: Inputs?
81	    private var timer: Timer?
82	    private var running: Token?
83	    private var generation = 0
84	
85	    /// The one serial queue the generations render on (a one-frame render
86	    /// queue, beside the eyedropper's and Save Frame's).
87	    private static let queue = DispatchQueue(label: "com.kgalligan.framejob.lookGallery")
88	    /// Every gallery, weakly, for `playheadMoved(in:)`. Main thread.
89	    private static let live = NSHashTable<LookGallery>.weakObjects()
90	
91	    init() {
92	        Self.live.add(self)
93	    }
94	
95	    /// Open, and either asked for inputs it has not shown or still rendering.
96	    var isPending: Bool {
97	        guard open, let latest else { return false }
98	        return !latest.same(rendered) || running != nil
99	    }
100	
101	    // MARK: - Updates
102	
103	    func update(
104	        from view: LookGalleryView, document: ProjectDocument?, targets: [ClipSnapshot],
105	        open: Bool
106	    ) {
107	        guard view === self.view else { return }
108	        self.document = document
109	        self.targets = targets
110	        self.open = open
111	        reschedule()
112	    }
113	
114	    /// The playhead moved in `document`: each of its live galleries asks again.
115	    static func playheadMoved(in document: ProjectDocument) {
116	        for gallery in live.allObjects where gallery.document === document {
117	            gallery.reschedule()
118	        }
119	    }
120	
121	    private func reschedule() {
122	        guard open, let document, let first = targets.first else {
123	            latest = nil
124	            cancel()
125	            return
126	        }
127	        let inputs = Inputs(
128	            project: document.editedProject, ids: targets.map(\.id),
129	            time: Self.time(first: first, playhead: document.playhead))
130	        latest = inputs
131	        if inputs.same(scheduled) { return }
132	        cancel()
133	        scheduled = inputs
134	        if inputs.same(rendered) { return }
135	        let timer = Timer(timeInterval: Self.settle, repeats: false) { [weak self] _ in
136	            self?.fire()
137	        }
138	        RunLoop.main.add(timer, forMode: .common)
139	        self.timer = timer
140	    }
141	
142	    /// Stops the timer and supersedes a running generation; what was last
143	    /// scheduled falls back to what the thumbnails show.
144	    private func cancel() {
145	        timer?.invalidate()
146	        timer = nil
147	        running?.cancel()
148	        running = nil
149	        scheduled = rendered
150	    }
151	
152	    // MARK: - A generation
153	
154	    private func fire() {
155	        timer = nil
156	        guard open, let view, view.window != nil, let document, let inputs = scheduled,
157	              !inputs.same(rendered)
158	        else {
159	            // Nothing rendered, so a later update with these inputs must arm again.
160	            scheduled = rendered
161	            return
162	        }
163	        generation += 1
164	        let number = generation
165	        let token = Token()
166	        running = token
167	        func trial(_ edit: ReelEdit?) -> ReelProject? {
168	            switch edit {
169	            case .applied(let project)?: return project
170	            case .identity?: return inputs.project
171	            default: return nil
172	            }
173	        }
174	        let luts = Self.luts(in: inputs.project.snapshot).map(\.id)
175	        let trials: [ReelProject?] = Self.tiles.map { tile in
176	            trial(try? inputs.project.applying(Self.op(tile, clips: inputs.ids)))
177	        } + luts.map { lut in
178	            trial(try? inputs.project.applying(Self.op(lut: lut, clips: inputs.ids)))
179	        }
180	        let urls = document.mediaURLs()
181	        let graphics = GraphicRegistry.shared.snapshot(for: document.recipeKey)
182	        var dump: URL?
183	        #if FRAMEJOB_DEV_TOOLS
184	        if let folder = UserDefaults.standard.string(forKey: Self.dumpKey), !folder.isEmpty {
185	            dump = URL(fileURLWithPath: folder).appendingPathComponent(String(number))
186	        }
187	        #endif
188	        Self.queue.async { [weak self] in
189	            var images: [CGImage?] = []
190	            for trial in trials {
191	                if token.isCancelled { return }
192	                images.append(trial.flatMap {
193	                    Exporter.renderFrame(
194	                        project: $0, urls: urls, at: inputs.time, maxWidth: Self.thumbnailWidth,
195	                        options: .none, graphics: graphics)
196	                })
197	            }
198	            if token.isCancelled { return }
199	            let names = Self.tiles.map { $0?.rawValue ?? "none" } + luts.map { "lut-\($0)" }
200	            if let dump { Self.write(images, names, generation: number, inputs: inputs, to: dump) }
201	            DispatchQueue.main.async {
202	                guard let self, self.running === token, !token.isCancelled else { return }
203	                self.running = nil
204	                self.thumbnails = Array(images.prefix(Self.tiles.count))
205	                self.lutThumbnails = [:]
206	                for (lut, image) in zip(luts, images.dropFirst(Self.tiles.count)) {
207	                    self.lutThumbnails[lut] = image
208	                }
209	                self.rendered = inputs
210	                self.view?.showThumbnails()
211	            }
212	        }
213	    }
