215	    /// The dev dump: the PNGs (the nine, then `lut-<id>`), then the
216	    /// manifest, last, with `tiles` the names in order.
217	    private static func write(
218	        _ images: [CGImage?], _ names: [String], generation: Int, inputs: Inputs, to folder: URL
219	    ) {
220	        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
221	        var missing: [String] = []
222	        for (name, image) in zip(names, images) {
223	            guard let image else {
224	                missing.append(name)
225	                continue
226	            }
227	            _ = try? FrameWriter.write(
228	                image, as: .png, to: folder.appendingPathComponent(name + ".png"))
229	        }
230	        let manifest: [String: Any] = [
231	            "generation": generation, "t": inputs.time, "clips": inputs.ids, "missing": missing,
232	            "tiles": names,
233	        ]
234	        if let data = try? JSONSerialization.data(withJSONObject: manifest) {
235	            try? data.write(to: folder.appendingPathComponent("manifest.json"))
236	        }
237	    }
