242	    /// source pixels of their own, or an adjustment clip.
243	    static func targets(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot) -> [ClipSnapshot] {
244	        clips.filter {
245	            InspectorTab.hasPixels($0, in: snapshot)
246	                && (InspectorTab.hasSourcePixels($0, in: snapshot) || InspectorTab.isAdjustment($0))
247	        }
