251	    /// its amount (1 on a clip with none), or `look: null` for None.
252	    static func op(_ kind: LookKind?, clips: [UInt32]) -> ReelOp {
253	        .setVideo(clips: clips, patch: VideoPatch(look: .some(kind.map { LookPatch(kind: $0) })))
254	    }
255	
256	    /// What a LUT's tile or menu item sends: `{kind: lut, media}`, no amount.
257	    static func op(lut media: UInt32, clips: [UInt32]) -> ReelOp {
258	        .setVideo(clips: clips, patch: VideoPatch(look: .some(LookPatch(kind: .lut, media: media))))
259	    }
