266	    /// A LUT's tile and item title: its name less a trailing `.cube`.
267	    static func lutName(_ media: MediaSnapshot) -> String {
268	        let name = media.name
269	        return name.lowercased().hasSuffix(".cube") ? String(name.dropLast(5)) : name
270	    }
