272	    /// The thumbnail time: the playhead inside the first clip, else its first
273	    /// frame.
274	    static func time(first: ClipSnapshot, playhead: Ticks) -> Ticks {
275	        first.start <= playhead && playhead < first.end ? playhead : first.start
276	    }
