278	    /// `.some(kind)` when every look is that kind, `.some(nil)` when none has
279	    /// a look, nil when they disagree or there are none.
280	    static func shared(_ looks: [LookProps?]) -> LookKind?? {
281	        guard let first = looks.first else { return nil }
282	        let kind = first?.kind
283	        return looks.allSatisfy({ $0?.kind == kind }) ? .some(kind) : nil
284	    }
285	
286	    /// "Warm 80%" when kind, LUT and amount are shared (a LUT by `names`,
287	    /// "LUT" when it has none), "none" when no clip has a look, "mixed"
288	    /// otherwise.
289	    static func summary(_ looks: [LookProps?], names: [UInt32: String] = [:]) -> String {
290	        guard let first = looks.first else { return "none" }
291	        guard looks.allSatisfy({ $0 == first }) else { return "mixed" }
292	        guard let look = first else { return "none" }
293	        let name = look.kind == .lut ? look.media.flatMap { names[$0] } ?? "LUT"
294	            : look.kind.displayName
295	        return name + String(format: " %.0f%%", look.amount * 100)
