365	    /// the id learned as Add Background ▸ Image… learns it
366	    /// (`backgroundMedia(for:in:)`: the id `add_media` mints, or the row a
367	    /// file already in the list holds). Off-event, so grouped explicitly. A
368	    /// refused file is the document's error sheet and changes nothing.
369	    func importLUT(from url: URL, into document: ProjectDocument, clips: [UInt32]) {
370	        MediaImporter.probe(url: url, mayAsk: true) { result in
371	            do {
372	                let descriptor = try result.get()
373	                let add = ReelOp.addMedia(descriptor: descriptor)
374	                guard let id = try Self.backgroundMedia(for: descriptor, in: document.project)
375	                else {
376	                    NSSound.beep()
377	                    return
378	                }
379	                let look = LookGallery.op(lut: id, clips: clips)
380	                document.performGroupedEdit("Import LUT", [add, look])
