387	    /// What a tag SAYS: `.some(kind)` for an index into the vocabulary,
388	    /// `.some(nil)` for None, nil for a tag no builder writes.
389	    private func lookKind(_ tag: Int) -> LookKind?? {
390	        if tag == Self.lookNoneTag { return .some(nil) }
