396	    /// The half of `validateUserInterfaceItem` this file owns; nil is "not
397	    /// mine". An item is on when every target's OWN look is its kind (None:
398	    /// no look; a LUT's item: that LUT), dashed when some but not all are
399	    /// (GR-7 [b] (3)), off otherwise; enabled exactly when there is a target.
400	    func validateLookAction(_ action: Selector, item: any NSValidatedUserInterfaceItem) -> Bool? {
401	        guard action == #selector(setLook(_:)) else { return nil }
402	        let targets = lookTargets
403	        let menuItem = item as? NSMenuItem
404	        if menuItem?.tag == Self.lookLUTTag {
405	            let lut = (menuItem?.representedObject as? NSNumber)?.uint32Value
406	            let carrying = targets.filter {
407	                $0.videoProps.look?.kind == .lut && $0.videoProps.look?.media == lut
408	            }.count
409	            menuItem?.state = carrying == 0 ? .off : (carrying < targets.count ? .mixed : .on)
410	        } else if let tagged = lookKind(menuItem?.tag ?? Int.min) {
411	            let carrying = targets.filter { $0.videoProps.look?.kind == tagged }.count
412	            menuItem?.state =
413	                carrying == 0 ? .off : (carrying == targets.count ? .on : .mixed)
414	        } else {
415	            menuItem?.state = .off
416	        }
417	        return !targets.isEmpty
418	    }
