423	/// `.cube` 3D LUTs as media (spec §11 GR-8): the file type File ▸ Add Media…
424	/// lists, the probe `MediaImporter.probe(url:)` dispatches a `.cube` to, and
425	/// the one read of a LUT's bytes, which the import probe and the
426	/// compositor's `LutTextures` share — both parse through the core
427	/// (`ReelCube.parse`), so a file the import accepted is the file that draws.
428	///
429	/// A LUT has no picture, sound or duration of its own: its descriptor is
430	/// kind `lut`, 0×0, duration 0, no flags, which is what `add_media` holds a
431	/// `lut` row to. It gets no caches (`generateCaches(for:url:in:)` returns at
432	/// once for one).
433	extension MediaImporter {
434	    /// The `.cube` file type: the system's when one is declared for the
435	    /// extension, else the dynamic type the extension names, which an open
436	    /// panel matches by the same extension.
437	    static let lutType: UTType = UTType(filenameExtension: "cube") ?? .data
438	
439	    /// Whether `url` names a `.cube` file, by its extension in any case.
440	    static func isLUT(_ url: URL) -> Bool {
441	        url.pathExtension.lowercased() == "cube"
442	    }
443	
444	    /// The file's lattice. Reads at most `ReelCube.maxBytes + 1` bytes, so a
445	    /// larger file is refused in the core's own sentence without being read
446	    /// whole. Throws the reading error, or the core's `ReelCoreError`.
447	    static func readLUT(_ url: URL) throws -> CubeLattice {
448	        let handle = try FileHandle(forReadingFrom: url)
449	        defer { try? handle.close() }
450	        let data = try handle.read(upToCount: ReelCube.maxBytes + 1) ?? Data()
451	        return try ReelCube.parse(data)
452	    }
