454	    /// The `media[]` descriptor of a `.cube` file, once the core has read it
455	    /// whole. A file it refuses is `ImportError.undecodable` in GR-8's words
456	    /// — `“Film.cube” is not a LUT Frame Job reads: line 2: LUT_3D_SIZE 200 is
457	    /// outside 2–65.` — and so is a file that cannot be opened, in
458	    /// `unreadable`'s words: `undecodable` is final, where `unreadable` would
459	    /// offer the file to the ffmpeg step (`invitesFFmpeg`).
460	    static func probeLUT(_ url: URL) throws -> MediaDescriptor {
461	        do {
462	            _ = try readLUT(url)
463	        } catch let refused as ReelCoreError {
464	            throw ImportError.undecodable(
465	                url,
466	                sentence: "“\(url.lastPathComponent)” is not a LUT Frame Job reads: "
467	                    + "\(refused.message).")
468	        } catch {
469	            throw ImportError.undecodable(
470	                url, sentence: "Could not read \(url.lastPathComponent).")
471	        }
472	        return MediaDescriptor(
473	            path: url.path, bookmark: bookmarkString(for: url), kind: .lut, duration: 0,
474	            width: 0, height: 0, fps: .thirty, hasVideo: false, hasAudio: false,
475	            hasAlpha: false)
476	    }
