482	/// A `.cube` file's table as the core read it (`ReelCube.parse`): `size`
483	/// points an axis and `size³` rows of red, green and blue, red changing
484	/// fastest — a 3D texture's texel order.
485	struct CubeLattice {
486	    let size: Int
487	    let rgb: [Float]
488	}
