513	    private enum Entry {
514	        case texture(MTLTexture)
515	        case failed
516	    }
517	
518	    private let device: MTLDevice
519	    private let lock = NSLock()
520	    private var cache = LRUCache<Key, Entry>(limit: LutTextures.capacity)
521	
522	    init(device: MTLDevice) {
523	        self.device = device
524	    }
525	
526	    @available(*, unavailable) required init?(coder: NSCoder) {
527	        fatalError("LutTextures does not support NSCoder")
528	    }
