530	    /// The lattice of the `.cube` file at `url`, read and uploaded on a miss;
531	    /// nil when the file is missing, refused by the core or cannot be
532	    /// uploaded.
533	    func texture(at url: URL) -> MTLTexture? {
534	        let path = url.standardizedFileURL.path
535	        guard let attributes = try? FileManager.default.attributesOfItem(atPath: path),
536	            let bytes = (attributes[.size] as? NSNumber)?.intValue,
537	            let modified = attributes[.modificationDate] as? Date
538	        else { return nil }
539	        let key = Key(path: path, size: bytes, modified: modified)
540	        lock.lock()
541	        defer { lock.unlock() }
542	        if let hit = cache.value(for: key) {
543	            if case .texture(let texture) = hit { return texture }
544	            return nil
545	        }
546	        let made = (try? MediaImporter.readLUT(url)).flatMap { upload($0) }
547	        cache.insert(made.map { .texture($0) } ?? .failed, for: key)
548	        return made
549	    }
550	
551	    /// The table as `rgba16Float` texels, each value clamped to 0–1 and
552	    /// alpha 1, converted to half floats by vImage (round to nearest).
553	    private func upload(_ lattice: CubeLattice) -> MTLTexture? {
554	        let n = lattice.size
555	        let points = n * n * n
556	        guard n >= 2, lattice.rgb.count == points * 3 else { return nil }
557	        var rgba = [Float](repeating: 1, count: points * 4)
558	        for point in 0..<points {
559	            for channel in 0..<3 {
560	                rgba[point * 4 + channel] = min(max(lattice.rgb[point * 3 + channel], 0), 1)
561	            }
562	        }
563	        let count = rgba.count
564	        var halves = [UInt16](repeating: 0, count: count)
565	        let converted: Bool = rgba.withUnsafeMutableBytes { source in
566	            halves.withUnsafeMutableBytes { target in
567	                guard let from = source.baseAddress, let to = target.baseAddress else {
568	                    return false
569	                }
570	                var src = vImage_Buffer(
571	                    data: from, height: 1, width: vImagePixelCount(count),
572	                    rowBytes: source.count)
573	                var dst = vImage_Buffer(
574	                    data: to, height: 1, width: vImagePixelCount(count),
575	                    rowBytes: target.count)
576	                return vImageConvert_PlanarFtoPlanar16F(&src, &dst, vImage_Flags(kvImageNoFlags))
577	                    == kvImageNoError
578	            }
579	        }
580	        guard converted else { return nil }
581	        let descriptor = MTLTextureDescriptor()
582	        descriptor.textureType = .type3D
583	        descriptor.pixelFormat = .rgba16Float
584	        descriptor.width = n
585	        descriptor.height = n
586	        descriptor.depth = n
587	        descriptor.usage = [.shaderRead]
588	        descriptor.storageMode = .managed
589	        guard let texture = device.makeTexture(descriptor: descriptor) else { return nil }
590	        let written: Bool = halves.withUnsafeBytes { bytes in
591	            guard let base = bytes.baseAddress else { return false }
592	            texture.replace(
593	                region: MTLRegionMake3D(0, 0, 0, n, n, n), mipmapLevel: 0, slice: 0,
594	                withBytes: base, bytesPerRow: n * 8, bytesPerImage: n * n * 8)
595	            return true
596	        }
597	        guard written else { return nil }
598	        texture.label = "Frame Job LUT"
599	        return texture
600	    }
601	}
602	//! The look vocabulary (spec §11 GR-7, format 15):
603	//! [`Look`], the `video.look` a clip carries — one of the eight built-in
604	//! [`LookKind`]s or an imported `.cube` LUT (`lut`, GR-8, naming its media),
605	//! and how much of it — and each built-in kind's [`LookDefinition`], the
606	//! DATA the compositor bakes.
607	//!
608	//! **Rust decides, Metal does** (spec §7): a look is defined here, as Color's
609	//! four keys, Light's nine and a [`SplitTone`], and published in the recipe
610	//! as that definition; the app bakes it on the GPU into a 33³ lattice with
611	//! the layer stage's own functions and mixes it at step 4d. Nothing here is
612	//! a colour table: the eight are Frame Job's own first numbers (tuned by the
613	//! owner at GR7), built from the textbook operations tone already uses — the
614	//! Concat rule (`designs/adr/effects-survey.md`) stands.
615	//!
616	//! Re-exported whole by `model_props.rs`, which `model.rs` re-exports whole
617	//! in turn, so `crate::model::Look` resolves like every other property type.
