812	//! A `.cube` 3D LUT file read into its lattice (spec §11 GR-8): the one
813	//! parser, which `ffi_cube.rs` exports for the app's import probe and its
814	//! texture upload, so a file the import accepted is the file the compositor
815	//! draws.
816	//!
817	//! **What is read** (GR-8 choice 7): 3D only; `LUT_3D_SIZE` 2–65; `TITLE`;
818	//! `#` comment lines; blank lines; CRLF; a UTF-8 BOM; `DOMAIN_MIN 0 0 0`,
819	//! `DOMAIN_MAX 1 1 1` and `LUT_3D_INPUT_RANGE 0 1`, which are the defaults
820	//! and so change nothing; table rows of three finite numbers, any value
821	//! (the compositor clamps to 0–1 when it draws). Everything else is
822	//! REFUSED by name rather than guessed at — a 1D LUT, another size, a
823	//! domain that is not the default, an unknown keyword, a keyword after the
824	//! table, a short or long table, a token that is not a number — in a
825	//! lowercase sentence naming the 1-based line and what was on it, which the
826	//! app prefixes with the file's name.
827	//!
828	//! The table's order is the format's: **red changes fastest**, then green,
829	//! then blue, and [`Cube::rgb`] keeps it, so row `r + g·n + b·n²` is the
830	//! output for input `(r, g, b) / (n − 1)` — exactly a 3D texture's texel
831	//! order, which is why the app uploads it unchanged.
832	//!
833	//! Written from the format's own description; nothing of Concat (the
834	//! effects survey's licensing rule) is read or carried.
835	
836	use crate::format::RC_CUBE_MAX_BYTES;
837	
838	/// The smallest lattice read: two points an axis, the corners.
839	pub const CUBE_SIZE_MIN: u32 = 2;
840	/// The largest: 65 points an axis (274,625 rows), the size the common
841	/// grading tools write at most.
842	pub const CUBE_SIZE_MAX: u32 = 65;
843	
844	/// A parsed 3D LUT: `size` points an axis, and `size³` rows of red, green
845	/// and blue, red fastest, as the file listed them.
846	#[derive(Debug, Clone, PartialEq)]
847	pub struct Cube {
848	    pub size: u32,
849	    pub rgb: Vec<f32>,
850	}
851	
852	/// One keyword the parser has a rule for.
853	enum Keyword {
854	    Title,
855	    Size,
856	    DomainMin,
857	    DomainMax,
858	    InputRange,
859	    OneD,
860	    Unknown,
861	}
862	
863	impl Keyword {
864	    fn of(word: &str) -> Keyword {
865	        match word {
866	            "TITLE" => Keyword::Title,
867	            "LUT_3D_SIZE" => Keyword::Size,
868	            "DOMAIN_MIN" => Keyword::DomainMin,
869	            "DOMAIN_MAX" => Keyword::DomainMax,
870	            "LUT_3D_INPUT_RANGE" => Keyword::InputRange,
871	            "LUT_1D_SIZE" | "LUT_1D_INPUT_RANGE" => Keyword::OneD,
872	            _ => Keyword::Unknown,
873	        }
874	    }
875	}
876	
877	/// A token as a number: `Ok` only for a finite one, else the sentence that
878	/// names the token (`"0.5x" is not a number`, `nan is not a finite number`).
879	fn number(token: &str, line: usize) -> Result<f64, String> {
880	    match token.parse::<f64>() {
881	        Ok(value) if value.is_finite() => Ok(value),
882	        Ok(_) => Err(format!("line {line}: {token} is not a finite number")),
883	        Err(_) => Err(format!("line {line}: \"{token}\" is not a number")),
884	    }
885	}
886	
887	/// A keyword's numbers, exactly `count` of them, each finite.
888	fn numbers(word: &str, rest: &[&str], count: usize, line: usize) -> Result<Vec<f64>, String> {
889	    if rest.len() != count {
890	        let noun = if count == 1 { "number" } else { "numbers" };
891	        return Err(format!("line {line}: {word} needs {count} {noun}"));
892	    }
893	    rest.iter().map(|token| number(token, line)).collect()
894	}
895	
896	/// A domain line holding its default, or the sentence that names what it
897	/// holds instead.
898	fn default_domain(
899	    word: &str,
900	    rest: &[&str],
901	    want: &[f64],
902	    shown: &str,
903	    line: usize,
904	) -> Result<(), String> {
905	    let found = numbers(word, rest, want.len(), line)?;
906	    if found.iter().zip(want).all(|(a, b)| a == b) {
907	        Ok(())
908	    } else {
909	        Err(format!(
910	            "line {line}: {word} must be {shown}, not {}",
911	            rest.join(" ")
912	        ))
913	    }
914	}
915	
916	/// A table value as stored: an `f64` past `f32`'s range is held at its
917	/// largest finite value, which draws the same once clamped to 0–1.
918	fn stored(value: f64) -> f32 {
919	    (value as f32).clamp(-f32::MAX, f32::MAX)
920	}
921	
922	impl Cube {
923	    /// Reads a `.cube` file's bytes; `Err` is the rule's own sentence.
924	    pub fn parse(bytes: &[u8]) -> Result<Cube, String> {
925	        if bytes.len() > RC_CUBE_MAX_BYTES {
926	            return Err("the file is larger than 32 MB".to_string());
927	        }
928	        let text = match std::str::from_utf8(bytes) {
929	            Ok(text) if !text.contains('\0') => text,
930	            _ => return Err("the file is not text".to_string()),
931	        };
932	        let text = text.strip_prefix('\u{feff}').unwrap_or(text);
933	        let mut size: Option<u32> = None;
934	        let mut rgb: Vec<f32> = Vec::new();
935	        let mut rows: usize = 0;
936	        let mut wanted: usize = 0;
937	        for (index, raw) in text.lines().enumerate() {
938	            let line = index + 1;
939	            let trimmed = raw.trim();
940	            if trimmed.is_empty() || trimmed.starts_with('#') {
941	                continue;
942	            }
943	            let tokens: Vec<&str> = trimmed.split_whitespace().collect();
944	            let first = tokens[0];
945	            // A table row begins with something `f64` reads (`nan` and
946	            // `inf` included, refused below as not finite); a keyword with
947	            // a letter or an underscore. Anything else is a row whose first
948	            // token is not a number.
949	            let is_keyword = first.parse::<f64>().is_err()
950	                && first.starts_with(|c: char| c.is_ascii_alphabetic() || c == '_');
951	            if is_keyword {
952	                let keyword = Keyword::of(first);
953	                match keyword {
954	                    Keyword::OneD => {
955	                        return Err(format!(
956	                            "line {line}: {first} is a 1D LUT; only 3D LUTs are read"
957	                        ))
958	                    }
959	                    Keyword::Unknown => {
960	                        return Err(format!("line {line}: unknown keyword {first}"))
961	                    }
962	                    _ => {}
963	                }
964	                if rows > 0 {
965	                    return Err(format!("line {line}: {first} comes after the table"));
966	                }
967	                let rest = &tokens[1..];
968	                match keyword {
969	                    Keyword::Title => {}
970	                    Keyword::Size => {
971	                        if size.is_some() {
972	                            return Err(format!("line {line}: a second LUT_3D_SIZE"));
973	                        }
974	                        let value = numbers(first, rest, 1, line)?[0];
975	                        if value.fract() != 0.0 {
976	                            return Err(format!(
977	                                "line {line}: LUT_3D_SIZE {} is not a whole number",
978	                                rest[0]
979	                            ));
980	                        }
981	                        if value < f64::from(CUBE_SIZE_MIN) || value > f64::from(CUBE_SIZE_MAX) {
982	                            return Err(format!(
983	                                "line {line}: LUT_3D_SIZE {} is outside {CUBE_SIZE_MIN}–{CUBE_SIZE_MAX}",
984	                                rest[0]
985	                            ));
986	                        }
987	                        let n = value as u32;
988	                        size = Some(n);
989	                        wanted = (n as usize).pow(3);
990	                        rgb.reserve_exact(wanted * 3);
991	                    }
992	                    Keyword::DomainMin => {
993	                        default_domain(first, rest, &[0.0, 0.0, 0.0], "0 0 0", line)?
994	                    }
995	                    Keyword::DomainMax => {
996	                        default_domain(first, rest, &[1.0, 1.0, 1.0], "1 1 1", line)?
997	                    }
998	                    Keyword::InputRange => default_domain(first, rest, &[0.0, 1.0], "0 1", line)?,
999	                    Keyword::OneD | Keyword::Unknown => {}
1000	                }
1001	                continue;
1002	            }
1003	            let values = tokens
1004	                .iter()
1005	                .map(|token| number(token, line))
1006	                .collect::<Result<Vec<f64>, String>>()?;
1007	            if values.len() != 3 {
1008	                return Err(format!(
1009	                    "line {line}: a table row has 3 numbers, not {}",
1010	                    values.len()
1011	                ));
1012	            }
1013	            rows += 1;
1014	            // Only the rows the size asks for are kept; the rest are
1015	            // counted, so a long table is named by its count.
1016	            if size.is_some() && rows <= wanted {
1017	                rgb.extend(values.into_iter().map(stored));
1018	            }
1019	        }
1020	        let Some(size) = size else {
1021	            return Err("no LUT_3D_SIZE line".to_string());
1022	        };
1023	        if rows != wanted {
1024	            return Err(format!(
1025	                "LUT_3D_SIZE {size} needs {wanted} table rows, not {rows}"
1026	            ));
1027	        }
1028	        Ok(Cube { size, rgb })
1029	    }
1030	
1031	    /// Points an axis.
1032	    pub fn size(&self) -> u32 {
1033	        self.size
1034	    }
1035	
1036	    /// Copies the table into `out`, red fastest; false (and `out` untouched)
1037	    /// unless `out` holds exactly `size³ · 3` floats.
1038	    pub fn copy_rgb(&self, out: &mut [f32]) -> bool {
1039	        if out.len() != self.rgb.len() {
1040	            return false;
1041	        }
1042	        out.copy_from_slice(&self.rgb);
1043	        true
1044	    }
1045	}
1046	//! `.cube` LUTs as media and as looks (spec §11 GR-8): the rules a `lut`
1047	//! media row and a `video.look {kind: "lut", media}` obey, written once for
1048	//! every door that meets them.
1049	//!
1050	//! - **The row.** A LUT is media so it is referenced, relinked and
1051	//!   consolidated like footage, but it has no picture of its own: its row
1052	//!   carries no video, audio, alpha or duration ([`check_lut_fields`], which
1053	//!   `edit_track.rs`'s `check_media_fields` calls for `add_media`, a
1054	//!   relink's probe and a pasted media row), and it is never placed as a clip — `add_clip`,
1055	//!   `insert_clip`, `overwrite_clip` and `add_background` answer
1056	//!   [`lut_not_placeable`].
1057	//! - **The look.** `media` is required with `lut` and goes with nothing
1058	//!   else, and must name a `lut` media of the project
1059	//!   ([`Project::check_look_media`], beside `check_adjustment_video` on the
1060	//!   patch path and on every pasted group, and in `validate` for a file),
1061	//!   through [`Project::check_lut_reference`], which `media_color.rs`'s
1062	//!   `color.lut` shares. A
1063	//!   patch naming a built-in kind and no `media` drops a stored one
1064	//!   ([`normalise_look`]), so a built-in kind on a LUT clip replaces the LUT.
1065	//! - **An action's end** is never checked against the media list
1066	//!   (`set_action_end` checks shape only), so an end may name a LUT that is
1067	//!   not there: the evaluator reads such a look as NO look
1068	//!   ([`Project::evaluates_as_look`]), and `actions.rs` switches `media` at
1069	//!   the end like a `kind`, so an id is never interpolated.
1070	//! - **Removing a used LUT** ([`Project::remove_lut`]) refuses naming the
1071	//!   clips whose base look it is and the media whose Camera Log it is (spec
1072	//!   §11 GR-16, `media.color.lut`), or with `with_clips` clears those looks
